import hashlib

def compute_document_hash(file_bytes: bytes) -> str:
    return hashlib.sha256(file_bytes).hexdigest()

def _find_user_document_by_hash(db: Session, user_id: int, document_hash: str) -> Document | None:
    return (
        db.query(Document)
        .filter(Document.user_id == user_id, Document.document_hash == document_hash)
        .first()
    )


#get all documents
def get_user_documents(
    db: Session,
    user: User,
) -> list[Document]:

    documents = (
        db.query(Document)
        .filter(Document.user_id == user.id)
        .order_by(Document.created_at.desc())
        .all()
    )

    return documents

#get single document
def get_user_document(
    db: Session,
    user: User,
    document_id: int,
) -> Document:

    document = (
        db.query(Document)
        .filter(
            Document.id == document_id,
            Document.user_id == user.id,
        )
        .first()
    )

    if not document:
        raise HTTPException(
            status_code=404,
            detail="Document not found",
        )

    return document

