def reject(decision: Decision) -> None:
    """Turns a denial into the HTTP 429 the client sees. Retry-After is the standard header for "come back in N seconds"."""
    raise HTTPException(
        status_code=status.HTTP_429_TOO_MANY_REQUESTS,
        detail=decision.message,
        headers={
            "Retry-After": str(decision.retry_after),
            "X-RateLimit-Limit": str(decision.limit),
            "X-RateLimit-Reset": str(int(time.time()) + decision.retry_after),   # unix time when it is allowed again
        },
    )


# --- FastAPI dependencies -------------------------------------------------------------------------
# They depend on get_current_user, so they run AFTER login and can key on the user (an unauthenticated
# request is a 401 first). FastAPI caches get_current_user per request, so the user is not looked up twice.


def limit_ask(current_user: User = Depends(get_current_user)) -> None:
    """/ask and /ask/stream share one budget: per-minute burst first, then the daily cap."""
    if not settings.rate_limit_enabled:
        return

    # Burst before daily: someone hammering past the burst limit never spends daily budget.
    burst = take_token(f"rl:ask:burst:{current_user.id}", settings.ask_per_minute, 60, "questions")
    if not burst.allowed:
        reject(burst)

    daily = count_today(f"rl:ask:day:{current_user.id}", settings.ask_per_day, "questions")
    if not daily.allowed:
        reject(daily)

// axios error -> ApiError
export function toApiError(error) {
  if (error instanceof ApiError) return error

  const response = error?.response
  if (!response) {
    // No answer at all: the backend is down, VITE_API_URL is wrong, or the browser blocked the call (CORS).
    return new ApiError('Cannot reach the server. Check that the backend is running.', { code: 'network' })
  }

  const { status, data, headers } = response
  return errorFromStatus(status, data?.detail, headers?.['retry-after'])
}

// An HTTP error status (+ the backend's `detail` and the Retry-After header) -> ApiError. Shared by axios calls and
// the streaming chat call (fetch).
export function errorFromStatus(status, rawDetail, retryAfterHeader) {
  const detail = detailText(rawDetail)

  if (status === 401) return new ApiError('Your session has expired. Please sign in again.', { status, code: 'auth' })
  if (status === 404) return new ApiError(detail || 'Not found.', { status, code: 'not_found' })
  if (status === 413) return new ApiError('That file is too large (20 MB maximum).', { status, code: 'too_large' })
  if (status === 422) return new ApiError(detail || 'Some of the information is not valid.', { status, code: 'validation' })
  if (status === 429) {
    return new ApiError(detail || 'Too many requests. Please slow down.', {
      status,
      code: 'rate_limited',
      retryAfter: parseRetryAfter(retryAfterHeader),
    })
  }
  if (status >= 500) return new ApiError(detail || 'The server had a problem. Please try again.', { status, code: 'server' })
  return new ApiError(detail || `The request failed (${status}).`, { status })
}

// The backend's citation -> what the chat shows.
// Backend: { marker: "[1]", document_id, source_name, page_number, slide_number, section_title, sheet_name,
//            row_start, row_end, snippet,
//            file_path, start_line, end_line, language }   <- source code only (all null for documents)

export function toCitation(raw) {
  return {
    n: Number.parseInt(String(raw.marker).replace(/\D/g, ''), 10),
    documentId: raw.document_id,
    // CODEBASE-FEATURE: for code the path is the title (inside a zip source_name is the zip, file_path the file)
    filename: raw.file_path || raw.source_name || 'Document',
    filePath: raw.file_path || null,
    language: raw.language || null,
    startLine: raw.start_line || null,
    endLine: raw.end_line || null,
    isCode: Boolean(raw.language || raw.file_path),
    location: locationOf(raw),
    shortLocation: shortLocationOf(raw),
    snippet: raw.snippet || '',
  }
}

